  1→<!DOCTYPE html>
  2→<html lang="en">
  3→<head>
  4→<meta charset="UTF-8">
  5→<meta name="viewport" content="width=device-width, initial-scale=1.0">
  6→<title>IB Resume BA — Design System</title>
  7→<link rel="preconnect" href="https://fonts.googleapis.com">
  8→<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  9→<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Libre+Baskerville:ital,wght@0,400;0,700;1,400&family=Lora:ital,wght@0,400;0,500;0,600;1,400;1,500&family=DM+Sans:wght@300;400;500;600;700&family=IBM+Plex+Sans:wght@300;400;500;600&family=Space+Grotesk:wght@400;500;600&family=Inter:wght@300;400;500;600;700&family=DM+Mono:wght@400;500&family=JetBrains+Mono:wght@400;500&family=Source+Code+Pro:wght@400;500&family=Fira+Code:wght@400;500&family=Inconsolata:wght@400;500;700&family=Instrument+Serif:ital@0;1&display=swap" rel="stylesheet">
 10→<style>
 11→:root {
 12→  --heading-font: 'Playfair Display', serif;
 13→  --body-font: 'Inter', sans-serif;
 14→  --mono-font: 'DM Mono', monospace;
 15→  --accent-font: 'Inter', sans-serif;
 16→  --accent-gold: #C9A96E;
 17→  --bg-body: #0A0A0A;
 18→  --bg-card: #141312;
 19→  --text-primary: #F5F5F5;
 20→  --text-secondary: #888888;
 21→  --color-green: #2ECC71;
 22→  --color-red: #E74C3C;
 23→  --color-orange: #F39C12;
 24→  --border-radius: 6px;
 25→  --btn-radius: 6px;
 26→  --input-radius: 6px;
 27→}
 28→*{margin:0;padding:0;box-sizing:border-box}
 29→body{background:var(--bg-body);color:var(--text-primary);font-family:var(--body-font);line-height:1.6}
 30→
 31→/* ─── TAB NAV ─── */
 32→.tab-nav{position:sticky;top:0;z-index:100;display:flex;gap:1px;background:rgba(10,10,10,0.97);backdrop-filter:blur(12px);padding:0 8px;border-bottom:1px solid rgba(255,255,255,0.08);overflow-x:auto;-webkit-overflow-scrolling:touch}
 33→.tab-nav::-webkit-scrollbar{height:0}
 34→.tab-btn{padding:12px 18px;background:transparent;border:none;border-bottom:2px solid transparent;color:var(--text-secondary);font-family:'Inter',sans-serif;cursor:pointer;font-size:11px;font-weight:600;letter-spacing:0.04em;text-transform:uppercase;transition:all .2s;white-space:nowrap}
 35→.tab-btn.active{color:var(--accent-gold);border-bottom-color:var(--accent-gold);background:rgba(201,169,110,0.06)}
 36→.tab-btn:hover:not(.active){color:#ccc}
 37→.tab-content{display:none;padding:0}
 38→.tab-content.active{display:block}
 39→
 40→/* ─── FLOATING CONTROL PANEL ─── */
 41→.ctrl-panel{position:fixed;bottom:20px;right:20px;width:300px;max-height:80vh;background:rgba(20,20,20,0.97);backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.1);border-radius:8px;z-index:500;font-family:'Inter',sans-serif;overflow:hidden;transition:all .3s}
 42→.ctrl-panel.collapsed{max-height:42px}
 43→.ctrl-header{display:flex;justify-content:space-between;align-items:center;padding:10px 14px;background:rgba(255,255,255,0.04);border-bottom:1px solid rgba(255,255,255,0.08);cursor:move;user-select:none}
 44→.ctrl-header h3{font-size:11px;letter-spacing:0.08em;text-transform:uppercase;color:#aaa;font-weight:600}
 45→.ctrl-header button{background:none;border:none;color:#888;font-size:18px;cursor:pointer;padding:0 4px}
 46→.ctrl-body{padding:8px 12px;overflow-y:auto;max-height:calc(80vh - 42px)}
 47→.ctrl-group{margin-bottom:10px}
 48→.ctrl-group label{display:block;font-size:9px;text-transform:uppercase;letter-spacing:0.1em;color:#666;margin-bottom:3px;font-weight:600}
 49→.ctrl-group select{width:100%;background:#1a1a1a;color:#ccc;border:1px solid rgba(255,255,255,0.1);border-radius:4px;padding:6px 8px;font-size:11px;font-family:'Inter',sans-serif;cursor:pointer;outline:none}
 50→.ctrl-group select:focus{border-color:var(--accent-gold)}
 51→.ctrl-divider{border:none;border-top:1px solid rgba(255,255,255,0.06);margin:10px 0}
 52→.btn-reset{width:100%;padding:8px;background:rgba(231,76,60,0.12);color:#E74C3C;border:1px solid rgba(231,76,60,0.2);border-radius:4px;font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:0.08em;cursor:pointer;margin-bottom:8px;font-family:'Inter',sans-serif}
 53→.btn-reset:hover{background:rgba(231,76,60,0.2)}
 54→
 55→/* ─── DESIGN COMPARE TAB ─── */
 56→.dc-wrap{padding:40px 24px 100px;max-width:1400px;margin:0 auto}
 57→.dc-title{font-size:28px;color:#fff;margin-bottom:6px;font-weight:500;letter-spacing:-0.02em;font-family:'IBM Plex Sans',sans-serif}
 58→.dc-sub{font-size:13px;color:#666;margin-bottom:50px;line-height:1.6}
 59→.dc-section{margin-bottom:60px}
 60→.dc-section-title{font-size:11px;text-transform:uppercase;letter-spacing:0.14em;color:#D4A853;margin-bottom:16px;font-weight:600;padding-bottom:8px;border-bottom:1px solid rgba(255,255,255,0.06);font-family:'Inter',sans-serif}
 61→.dc-note{font-size:11px;color:#555;margin-bottom:12px;font-style:italic}
 62→.dc-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px}
 63→.dc-card{border:1px solid rgba(255,255,255,0.08);border-radius:4px;overflow:hidden;cursor:pointer;transition:all .2s;position:relative}
 64→.dc-card:hover{border-color:rgba(255,255,255,0.2);transform:translateY(-1px)}
 65→.dc-card.selected{border-color:var(--accent-gold);box-shadow:0 0 0 1px var(--accent-gold),0 0 20px rgba(201,169,110,0.15)}
 66→.dc-card.selected::after{content:'✓';position:absolute;top:6px;right:8px;width:18px;height:18px;background:var(--accent-gold);color:#000;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700}
 67→.dc-label{display:flex;justify-content:space-between;align-items:center;padding:6px 10px;background:rgba(255,255,255,0.03);border-bottom:1px solid rgba(255,255,255,0.05)}
 68→.dc-label span{font-size:10px;font-weight:600;color:#aaa}
 69→.dc-tag{font-size:7px;text-transform:uppercase;letter-spacing:0.06em;padding:2px 5px;border-radius:2px;font-weight:700}
 70→.dc-tag-cur{background:rgba(255,80,80,0.12);color:#ff6b6b}
 71→.dc-tag-alt{background:rgba(80,200,120,0.1);color:#50c878}
 72→.dc-preview{padding:16px 12px;min-height:60px}
 73→.dc-meta{padding:4px 10px;border-top:1px solid rgba(255,255,255,0.04);background:rgba(255,255,255,0.015)}
 74→.dc-meta code{font-family:'JetBrains Mono',monospace;font-size:8px;color:#444;line-height:1.5}
 75→.dc-part-divider{margin:70px 0 50px;text-align:center}
 76→.dc-part-divider h2{font-size:18px;color:#fff;font-weight:500;margin-bottom:4px;font-family:'IBM Plex Sans',sans-serif}
 77→.dc-part-divider p{font-size:11px;color:#555}
 78→.dc-part-divider .bar{width:40px;height:1px;background:#D4A853;margin:12px auto 0}
 79→
 80→/* ─── GLOBAL COLORS SECTION ─── */
 81→.gc-section{margin-top:80px;padding-top:40px;border-top:1px solid rgba(255,255,255,0.08)}
 82→.gc-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:16px;margin-top:20px}
 83→.gc-item{background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.08);border-radius:6px;padding:14px}
 84→.gc-item label{display:block;font-size:9px;text-transform:uppercase;letter-spacing:0.1em;color:#666;margin-bottom:8px;font-weight:600}
 85→.gc-color-row{display:flex;align-items:center;gap:10px}
 86→.gc-color-row input[type="color"]{width:40px;height:32px;border:1px solid rgba(255,255,255,0.15);border-radius:4px;background:transparent;cursor:pointer;padding:2px}
 87→.gc-color-row input[type="text"]{flex:1;background:#1a1a1a;color:#ccc;border:1px solid rgba(255,255,255,0.1);border-radius:4px;padding:6px 8px;font-size:11px;font-family:'JetBrains Mono',monospace}
 88→.gc-swatch{width:100%;height:24px;border-radius:3px;margin-top:8px}
 89→
 90→/* ─── SAVE/EXPORT ─── */
 91→.save-section{margin-top:60px;text-align:center;padding:40px 0}
 92→.btn-save{padding:14px 40px;background:var(--accent-gold);color:#111;border:none;border-radius:6px;font-size:13px;font-weight:700;letter-spacing:0.04em;cursor:pointer;font-family:'Inter',sans-serif;transition:all .2s}
 93→.btn-save:hover{filter:brightness(1.1);transform:translateY(-1px)}
 94→.save-note{font-size:11px;color:#555;margin-top:10px}
 95→
 96→/* ─── MOCKUP PAGES ─── */
 97→.mock-page{padding:0;max-width:1200px;margin:0 auto}
 98→
 99→/* Ticker */
100→.ticker{background:rgba(255,255,255,0.02);border-bottom:1px solid rgba(255,255,255,0.05);padding:10px 0;overflow:hidden;white-space:nowrap}
101→.ticker-inner{display:inline-block;animation:tickscroll 30s linear infinite}
102→.ticker span{font-size:10px;font-weight:500;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-secondary);margin-right:40px}
103→@keyframes tickscroll{0%{transform:translateX(0)}100%{transform:translateX(-50%)}}
104→
105→/* Nav bar */
106→.mock-nav{display:flex;justify-content:space-between;align-items:center;padding:0 24px;height:49px;background:rgb(14,14,13);border-bottom:1px solid rgb(42,40,38)}
107→.mock-nav .logo{font-family:var(--body-font);font-size:15px;font-weight:500;color:var(--text-primary)}
108→.mock-nav .logo em{font-style:normal;color:var(--accent-gold);font-weight:600}
109→.mock-nav .nav-btns{display:flex;gap:8px}
110→.mock-nav .nav-btn{padding:6px 14px;border-radius:var(--btn-radius);font-size:11px;font-weight:600;cursor:pointer;font-family:var(--body-font);border:1px solid rgba(255,255,255,0.2);background:transparent;color:var(--text-primary);transition:all .2s}
111→.mock-nav .nav-btn:hover{background:rgba(255,255,255,0.08)}
112→.step-dots{display:flex;gap:6px}
113→.step-dot{width:40px;height:3px;border-radius:2px;background:rgba(255,255,255,0.15)}
114→.step-dot.active{background:var(--accent-gold)}
115→.step-dot.done{background:var(--accent-gold)}
116→
117→/* Hero layout */
118→.hero-split{display:flex;gap:60px;padding:80px 40px 60px;align-items:flex-start;min-height:calc(100vh - 200px)}
119→.hero-left{flex:1}
120→.hero-right{width:420px;flex-shrink:0}
121→.hero-label{font-size:10px;letter-spacing:0.15em;text-transform:uppercase;color:var(--text-secondary);margin-bottom:20px}
122→.hero-heading{font-family:var(--heading-font);font-size:62px;font-weight:400;line-height:0.93;letter-spacing:-1.55px;color:rgb(243,241,236);margin-bottom:8px}
123→.hero-accent{font-family:var(--accent-font);font-size:62px;font-weight:400;font-style:italic;color:var(--accent-gold);margin-bottom:24px;line-height:1.1}
124→.hero-desc{font-size:14px;color:var(--text-secondary);line-height:1.7;margin-bottom:40px;max-width:460px}
125→.stats-row{display:flex;gap:40px}
126→.stat-num{font-family:var(--heading-font);font-size:32px;font-weight:400;color:var(--text-primary)}
127→.stat-num sup{font-size:18px;vertical-align:super}
128→.stat-label{font-size:9px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-secondary);font-weight:500;margin-top:2px}
129→
130→/* Access card */
131→.access-card{background:rgba(0,0,0,0.8);border:1px solid rgb(26,26,26);border-radius:12px;padding:24px}
132→.access-card .card-label{font-size:9px;letter-spacing:0.14em;text-transform:uppercase;color:var(--text-secondary);font-weight:600;margin-bottom:4px}
133→.access-card .card-title{font-family:var(--heading-font);font-size:34px;font-weight:400;color:rgb(243,241,236);margin-bottom:8px}
134→.access-card .card-desc{font-size:13px;color:var(--text-secondary);margin-bottom:20px;line-height:1.5}
135→.form-label{font-size:10px;font-weight:600;letter-spacing:0.12em;text-transform:uppercase;color:rgb(161,161,161);margin-bottom:6px;display:block}
136→.form-input{width:100%;background:rgb(11,11,11);border:1px solid rgb(38,38,38);border-radius:var(--input-radius);padding:12px 16px;color:var(--text-primary);font-size:13px;font-family:var(--body-font);outline:none;margin-bottom:16px}
137→.form-input:focus{border-color:rgba(201,169,110,0.4)}
138→.form-input::placeholder{color:#555}
139→.btn-primary{width:100%;padding:12px;background:var(--accent-gold);color:rgb(17,17,17);border:none;border-radius:var(--btn-radius);font-size:12.5px;font-weight:600;cursor:pointer;font-family:var(--body-font);transition:all .2s}
140→.btn-primary:hover{filter:brightness(1.1)}
141→.card-footer{font-size:11px;color:#555;text-align:center;margin-top:16px;line-height:1.5}
142→
143→/* Upload page */
144→.upload-wrap{padding:80px 40px;max-width:700px;margin:0 auto}
145→.step-label{font-size:10px;letter-spacing:0.12em;text-transform:uppercase;color:var(--accent-gold);font-weight:600;margin-bottom:8px}
146→.page-heading{font-family:var(--heading-font);font-size:42px;font-weight:400;color:rgb(243,241,236);margin-bottom:8px}
147→.page-desc{font-size:14px;color:var(--text-secondary);margin-bottom:6px}
148→.page-features{font-size:12px;color:var(--accent-gold);margin-bottom:30px}
149→.upload-zone{border:2px dashed rgba(201,169,110,0.3);border-radius:var(--border-radius);padding:50px 24px;text-align:center;margin-bottom:30px;transition:all .2s}
150→.upload-zone:hover{border-color:rgba(201,169,110,0.5);background:rgba(201,169,110,0.03)}
151→.upload-icon{width:40px;height:40px;border:2px solid rgba(201,169,110,0.4);border-radius:50%;display:inline-flex;align-items:center;justify-content:center;color:var(--accent-gold);font-size:18px;margin-bottom:12px}
152→.upload-text{font-size:18px;color:var(--text-primary);font-weight:500;margin-bottom:6px}
153→.upload-hint{font-size:12px;color:var(--text-secondary)}
154→.form-actions{display:flex;justify-content:space-between;align-items:center}
155→.btn-back{background:transparent;border:1px solid rgba(255,255,255,0.15);color:var(--text-primary);padding:10px 24px;border-radius:var(--btn-radius);font-size:12px;font-weight:500;cursor:pointer;font-family:var(--body-font)}
156→.btn-continue{padding:10px 24px;background:var(--accent-gold);color:#111;border:none;border-radius:var(--btn-radius);font-size:12px;font-weight:600;cursor:pointer;font-family:var(--body-font)}
157→
158→/* About page */
159→.about-wrap{padding:80px 40px;max-width:700px;margin:0 auto}
160→.form-row{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px}
161→.form-group{display:flex;flex-direction:column}
162→.form-select{width:100%;background:rgb(11,11,11);border:1px solid rgb(38,38,38);border-radius:var(--input-radius);padding:12px 16px;color:var(--text-primary);font-size:13px;font-family:var(--body-font);outline:none;appearance:none;cursor:pointer}
163→
164→/* Banks page */
165→.banks-wrap{padding:80px 40px;max-width:700px;margin:0 auto}
166→.mode-toggle{display:flex;gap:0;margin:20px 0}
167→.mode-btn{padding:8px 18px;font-size:11px;font-weight:600;letter-spacing:0.04em;text-transform:uppercase;border:1px solid rgba(255,255,255,0.15);background:transparent;color:var(--text-secondary);cursor:pointer;font-family:var(--body-font);transition:all .2s}
168→.mode-btn:first-child{border-radius:var(--btn-radius) 0 0 var(--btn-radius)}
169→.mode-btn:last-child{border-radius:0 var(--btn-radius) var(--btn-radius) 0}
170→.mode-btn.active{background:rgba(255,255,255,0.1);color:var(--text-primary);border-color:rgba(255,255,255,0.25)}
171→.tier-tabs{display:flex;gap:0;margin:20px 0;background:rgba(255,255,255,0.04);border-radius:var(--border-radius);overflow:hidden}
172→.tier-tab{flex:1;padding:10px;font-size:11px;font-weight:500;text-align:center;border:none;background:transparent;color:var(--text-secondary);cursor:pointer;font-family:var(--body-font);transition:all .2s}
173→.tier-tab.active{background:rgba(255,255,255,0.08);color:var(--text-primary)}
174→.bank-pills{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}
175→.bank-pill{padding:8px 16px;border:1px solid rgba(255,255,255,0.15);border-radius:20px;font-size:12px;color:var(--text-secondary);cursor:pointer;transition:all .2s;font-family:var(--body-font)}
176→.bank-pill.selected{border-color:var(--accent-gold);color:var(--accent-gold);background:rgba(201,169,110,0.08)}
177→.bank-pill:hover{border-color:rgba(255,255,255,0.3)}
178→.search-bar{display:flex;gap:8px;margin:20px 0}
179→.search-bar input{flex:1;background:rgb(11,11,11);border:1px solid rgb(38,38,38);border-radius:var(--input-radius);padding:10px 16px;color:var(--text-primary);font-size:12px;font-family:var(--body-font)}
180→.search-bar button{padding:10px 20px;background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.15);border-radius:var(--btn-radius);color:var(--text-secondary);font-size:11px;font-weight:600;cursor:pointer;font-family:var(--body-font)}
181→
182→/* Results page */
183→.results-wrap{display:grid;grid-template-columns:1fr 340px;gap:24px;padding:24px;max-width:1200px;margin:0 auto}
184→.results-main{display:flex;flex-direction:column;gap:24px}
185→.results-sidebar{display:flex;flex-direction:column;gap:16px}
186→
187→/* Score card */
188→.score-card{background:var(--bg-card);border:1px solid rgba(255,255,255,0.08);border-radius:var(--border-radius);padding:24px;display:flex;gap:24px;align-items:center}
189→.score-circle{width:100px;height:100px;border-radius:50%;background:conic-gradient(var(--color-green) 0deg 342deg, rgba(46,204,113,0.15) 342deg);display:flex;flex-direction:column;align-items:center;justify-content:center;flex-shrink:0;position:relative}
190→.score-circle::after{content:'';position:absolute;inset:8px;border-radius:50%;background:var(--bg-card)}
191→.score-num{font-family:var(--heading-font);font-size:32px;font-weight:600;color:var(--color-green);position:relative;z-index:1}
192→.score-den{font-size:10px;color:var(--text-secondary);position:relative;z-index:1}
193→.score-info{flex:1}
194→.score-badge{display:inline-block;font-size:9px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;padding:4px 10px;border-radius:12px;background:rgba(46,204,113,0.12);color:var(--color-green);margin-bottom:8px}
195→.score-title{font-family:var(--heading-font);font-size:24px;font-weight:400;color:rgb(243,241,236);margin-bottom:6px;line-height:1.3}
196→.score-desc{font-size:13px;color:var(--text-secondary);line-height:1.5}
197→
198→/* Category bars */
199→.cat-bars{display:flex;gap:12px;margin-top:16px;flex-wrap:wrap}
200→.cat-bar{flex:1;min-width:80px}

