#!/usr/bin/env python3
"""
Generate complete interactive-mockup.html with all 20 Design Compare sections.
"""

html_content = """<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>IB Resume BA — Design System</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Libre+Baskerville:ital,wght@0,400;0,700;1,400&family=Lora:ital,wght@0,400;0,500;0,600;1,400;1,500&family=DM+Sans:wght@300;400;500;600;700&family=IBM+Plex+Sans:wght@300;400;500;600&family=Space+Grotesk:wght@400;500;600&family=Inter:wght@300;400;500;600;700&family=DM+Mono:wght@400;500&family=JetBrains+Mono:wght@400;500&family=Source+Code+Pro:wght@400;500&family=Fira+Code:wght@400;500&family=Inconsolata:wght@400;500;700&family=Instrument+Serif:ital@0;1&display=swap" rel="stylesheet">
<style>
:root {
  --heading-font: 'Playfair Display', serif;
  --body-font: 'Inter', sans-serif;
  --mono-font: 'DM Mono', monospace;
  --accent-font: 'Inter', sans-serif;
  --accent-gold: #C9A96E;
  --bg-body: #0A0A0A;
  --bg-card: #141312;
  --text-primary: #F5F5F5;
  --text-secondary: #888888;
  --color-green: #2ECC71;
  --color-red: #E74C3C;
  --color-orange: #F39C12;
  --border-radius: 6px;
  --btn-radius: 6px;
  --input-radius: 6px;
}
*{margin:0;padding:0;box-sizing:border-box}
body{background:var(--bg-body);color:var(--text-primary);font-family:var(--body-font);line-height:1.6}

/* ─── TAB NAV ─── */
.tab-nav{position:sticky;top:0;z-index:100;display:flex;gap:1px;background:rgba(10,10,10,0.97);backdrop-filter:blur(12px);padding:0 8px;border-bottom:1px solid rgba(255,255,255,0.08);overflow-x:auto;-webkit-overflow-scrolling:touch}
.tab-nav::-webkit-scrollbar{height:0}
.tab-btn{padding:12px 18px;background:transparent;border:none;border-bottom:2px solid transparent;color:var(--text-secondary);font-family:'Inter',sans-serif;cursor:pointer;font-size:11px;font-weight:600;letter-spacing:0.04em;text-transform:uppercase;transition:all .2s;white-space:nowrap}
.tab-btn.active{color:var(--accent-gold);border-bottom-color:var(--accent-gold);background:rgba(201,169,110,0.06)}
.tab-btn:hover:not(.active){color:#ccc}
.tab-content{display:none;padding:0}
.tab-content.active{display:block}

/* ─── FLOATING CONTROL PANEL ─── */
.ctrl-panel{position:fixed;bottom:20px;right:20px;width:300px;max-height:80vh;background:rgba(20,20,20,0.97);backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,0.1);border-radius:8px;z-index:500;font-family:'Inter',sans-serif;overflow:hidden;transition:all .3s}
.ctrl-panel.collapsed{max-height:42px}
.ctrl-header{display:flex;justify-content:space-between;align-items:center;padding:10px 14px;background:rgba(255,255,255,0.04);border-bottom:1px solid rgba(255,255,255,0.08);cursor:move;user-select:none}
.ctrl-header h3{font-size:11px;letter-spacing:0.08em;text-transform:uppercase;color:#aaa;font-weight:600}
.ctrl-header button{background:none;border:none;color:#888;font-size:18px;cursor:pointer;padding:0 4px}
.ctrl-body{padding:8px 12px;overflow-y:auto;max-height:calc(80vh - 42px)}
.ctrl-group{margin-bottom:10px}
.ctrl-group label{display:block;font-size:9px;text-transform:uppercase;letter-spacing:0.1em;color:#666;margin-bottom:3px;font-weight:600}
.ctrl-group select{width:100%;background:#1a1a1a;color:#ccc;border:1px solid rgba(255,255,255,0.1);border-radius:4px;padding:6px 8px;font-size:11px;font-family:'Inter',sans-serif;cursor:pointer;outline:none}
.ctrl-group select:focus{border-color:var(--accent-gold)}
.ctrl-divider{border:none;border-top:1px solid rgba(255,255,255,0.06);margin:10px 0}
.btn-reset{width:100%;padding:8px;background:rgba(231,76,60,0.12);color:#E74C3C;border:1px solid rgba(231,76,60,0.2);border-radius:4px;font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:0.08em;cursor:pointer;margin-bottom:8px;font-family:'Inter',sans-serif}
.btn-reset:hover{background:rgba(231,76,60,0.2)}

/* ─── DESIGN COMPARE TAB ─── */
.dc-wrap{padding:40px 24px 100px;max-width:1400px;margin:0 auto}
.dc-title{font-size:28px;color:#fff;margin-bottom:6px;font-weight:500;letter-spacing:-0.02em;font-family:'IBM Plex Sans',sans-serif}
.dc-sub{font-size:13px;color:#666;margin-bottom:50px;line-height:1.6}
.dc-section{margin-bottom:60px}
.dc-section-title{font-size:11px;text-transform:uppercase;letter-spacing:0.14em;color:#D4A853;margin-bottom:16px;font-weight:600;padding-bottom:8px;border-bottom:1px solid rgba(255,255,255,0.06);font-family:'Inter',sans-serif}
.dc-note{font-size:11px;color:#555;margin-bottom:12px;font-style:italic}
.dc-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px}
.dc-card{border:1px solid rgba(255,255,255,0.08);border-radius:4px;overflow:hidden;cursor:pointer;transition:all .2s;position:relative}
.dc-card:hover{border-color:rgba(255,255,255,0.2);transform:translateY(-1px)}
.dc-card.selected{border-color:var(--accent-gold);box-shadow:0 0 0 1px var(--accent-gold),0 0 20px rgba(201,169,110,0.15)}
.dc-card.selected::after{content:'✓';position:absolute;top:6px;right:8px;width:18px;height:18px;background:var(--accent-gold);color:#000;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700}
.dc-label{display:flex;justify-content:space-between;align-items:center;padding:6px 10px;background:rgba(255,255,255,0.03);border-bottom:1px solid rgba(255,255,255,0.05)}
.dc-label span{font-size:10px;font-weight:600;color:#aaa}
.dc-tag{font-size:7px;text-transform:uppercase;letter-spacing:0.06em;padding:2px 5px;border-radius:2px;font-weight:700}
.dc-tag-cur{background:rgba(255,80,80,0.12);color:#ff6b6b}
.dc-tag-alt{background:rgba(80,200,120,0.1);color:#50c878}
.dc-preview{padding:16px 12px;min-height:60px}
.dc-meta{padding:4px 10px;border-top:1px solid rgba(255,255,255,0.04);background:rgba(255,255,255,0.015)}
.dc-meta code{font-family:'JetBrains Mono',monospace;font-size:8px;color:#444;line-height:1.5}
.dc-part-divider{margin:70px 0 50px;text-align:center}
.dc-part-divider h2{font-size:18px;color:#fff;font-weight:500;margin-bottom:4px;font-family:'IBM Plex Sans',sans-serif}
.dc-part-divider p{font-size:11px;color:#555}
.dc-part-divider .bar{width:40px;height:1px;background:#D4A853;margin:12px auto 0}

/* ─── GLOBAL COLORS SECTION ─── */
.gc-section{margin-top:80px;padding-top:40px;border-top:1px solid rgba(255,255,255,0.08)}
.gc-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:16px;margin-top:20px}
.gc-item{background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.08);border-radius:6px;padding:14px}
.gc-item label{display:block;font-size:9px;text-transform:uppercase;letter-spacing:0.1em;color:#666;margin-bottom:8px;font-weight:600}
.gc-color-row{display:flex;align-items:center;gap:10px}
.gc-color-row input[type="color"]{width:40px;height:32px;border:1px solid rgba(255,255,255,0.15);border-radius:4px;background:transparent;cursor:pointer;padding:2px}
.gc-color-row input[type="text"]{flex:1;background:#1a1a1a;color:#ccc;border:1px solid rgba(255,255,255,0.1);border-radius:4px;padding:6px 8px;font-size:11px;font-family:'JetBrains Mono',monospace}
.gc-swatch{width:100%;height:24px;border-radius:3px;margin-top:8px}

/* ─── SAVE/EXPORT ─── */
.save-section{margin-top:60px;text-align:center;padding:40px 0}
.btn-save{padding:14px 40px;background:var(--accent-gold);color:#111;border:none;border-radius:6px;font-size:13px;font-weight:700;letter-spacing:0.04em;cursor:pointer;font-family:'Inter',sans-serif;transition:all .2s}
.btn-save:hover{filter:brightness(1.1);transform:translateY(-1px)}
.save-note{font-size:11px;color:#555;margin-top:10px}

/* ─── MOCKUP PAGES ─── */
.mock-page{padding:0;max-width:1200px;margin:0 auto}

/* Ticker */
.ticker{background:rgba(255,255,255,0.02);border-bottom:1px solid rgba(255,255,255,0.05);padding:10px 0;overflow:hidden;white-space:nowrap}
.ticker-inner{display:inline-block;animation:tickscroll 30s linear infinite}
.ticker span{font-size:10px;font-weight:500;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-secondary);margin-right:40px}
@keyframes tickscroll{0%{transform:translateX(0)}100%{transform:translateX(-50%)}}

/* Nav bar */
.mock-nav{display:flex;justify-content:space-between;align-items:center;padding:0 24px;height:49px;background:rgb(14,14,13);border-bottom:1px solid rgb(42,40,38)}
.mock-nav .logo{font-family:var(--body-font);font-size:15px;font-weight:500;color:var(--text-primary)}
.mock-nav .logo em{font-style:normal;color:var(--accent-gold);font-weight:600}
.mock-nav .nav-btns{display:flex;gap:8px}
.mock-nav .nav-btn{padding:6px 14px;border-radius:var(--btn-radius);font-size:11px;font-weight:600;cursor:pointer;font-family:var(--body-font);border:1px solid rgba(255,255,255,0.2);background:transparent;color:var(--text-primary);transition:all .2s}
.mock-nav .nav-btn:hover{background:rgba(255,255,255,0.08)}
.step-dots{display:flex;gap:6px}
.step-dot{width:40px;height:3px;border-radius:2px;background:rgba(255,255,255,0.15)}
.step-dot.active{background:var(--accent-gold)}
.step-dot.done{background:var(--accent-gold)}

/* Hero layout */
.hero-split{display:flex;gap:60px;padding:80px 40px 60px;align-items:flex-start;min-height:calc(100vh - 200px)}
.hero-left{flex:1}
.hero-right{width:420px;flex-shrink:0}
.hero-label{font-size:10px;letter-spacing:0.15em;text-transform:uppercase;color:var(--text-secondary);margin-bottom:20px}
.hero-heading{font-family:var(--heading-font);font-size:62px;font-weight:400;line-height:0.93;letter-spacing:-1.55px;color:rgb(243,241,236);margin-bottom:8px}
.hero-accent{font-family:var(--accent-font);font-size:62px;font-weight:400;font-style:italic;color:var(--accent-gold);margin-bottom:24px;line-height:1.1}
.hero-desc{font-size:14px;color:var(--text-secondary);line-height:1.7;margin-bottom:40px;max-width:460px}
.stats-row{display:flex;gap:40px}
.stat-num{font-family:var(--heading-font);font-size:32px;font-weight:400;color:var(--text-primary)}
.stat-num sup{font-size:18px;vertical-align:super}
.stat-label{font-size:9px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-secondary);font-weight:500;margin-top:2px}

/* Access card */
.access-card{background:rgba(0,0,0,0.8);border:1px solid rgb(26,26,26);border-radius:12px;padding:24px}
.access-card .card-label{font-size:9px;letter-spacing:0.14em;text-transform:uppercase;color:var(--text-secondary);font-weight:600;margin-bottom:4px}
.access-card .card-title{font-family:var(--heading-font);font-size:34px;font-weight:400;color:rgb(243,241,236);margin-bottom:8px}
.access-card .card-desc{font-size:13px;color:var(--text-secondary);margin-bottom:20px;line-height:1.5}
.form-label{font-size:10px;font-weight:600;letter-spacing:0.12em;text-transform:uppercase;color:rgb(161,161,161);margin-bottom:6px;display:block}
.form-input{width:100%;background:rgb(11,11,11);border:1px solid rgb(38,38,38);border-radius:var(--input-radius);padding:12px 16px;color:var(--text-primary);font-size:13px;font-family:var(--body-font);outline:none;margin-bottom:16px}
.form-input:focus{border-color:rgba(201,169,110,0.4)}
.form-input::placeholder{color:#555}
.btn-primary{width:100%;padding:12px;background:var(--accent-gold);color:rgb(17,17,17);border:none;border-radius:var(--btn-radius);font-size:12.5px;font-weight:600;cursor:pointer;font-family:var(--body-font);transition:all .2s}
.btn-primary:hover{filter:brightness(1.1)}
.card-footer{font-size:11px;color:#555;text-align:center;margin-top:16px;line-height:1.5}

/* Upload page */
.upload-wrap{padding:80px 40px;max-width:700px;margin:0 auto}
.step-label{font-size:10px;letter-spacing:0.12em;text-transform:uppercase;color:var(--accent-gold);font-weight:600;margin-bottom:8px}
.page-heading{font-family:var(--heading-font);font-size:42px;font-weight:400;color:rgb(243,241,236);margin-bottom:8px}
.page-desc{font-size:14px;color:var(--text-secondary);margin-bottom:6px}
.page-features{font-size:12px;color:var(--accent-gold);margin-bottom:30px}
.upload-zone{border:2px dashed rgba(201,169,110,0.3);border-radius:var(--border-radius);padding:50px 24px;text-align:center;margin-bottom:30px;transition:all .2s}
.upload-zone:hover{border-color:rgba(201,169,110,0.5);background:rgba(201,169,110,0.03)}
.upload-icon{width:40px;height:40px;border:2px solid rgba(201,169,110,0.4);border-radius:50%;display:inline-flex;align-items:center;justify-content:center;color:var(--accent-gold);font-size:18px;margin-bottom:12px}
.upload-text{font-size:18px;color:var(--text-primary);font-weight:500;margin-bottom:6px}
.upload-hint{font-size:12px;color:var(--text-secondary)}
.form-actions{display:flex;justify-content:space-between;align-items:center}
.btn-back{background:transparent;border:1px solid rgba(255,255,255,0.15);color:var(--text-primary);padding:10px 24px;border-radius:var(--btn-radius);font-size:12px;font-weight:500;cursor:pointer;font-family:var(--body-font)}
.btn-continue{padding:10px 24px;background:var(--accent-gold);color:#111;border:none;border-radius:var(--btn-radius);font-size:12px;font-weight:600;cursor:pointer;font-family:var(--body-font)}

/* About page */
.about-wrap{padding:80px 40px;max-width:700px;margin:0 auto}
.form-row{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px}
.form-group{display:flex;flex-direction:column}
.form-select{width:100%;background:rgb(11,11,11);border:1px solid rgb(38,38,38);border-radius:var(--input-radius);padding:12px 16px;color:var(--text-primary);font-size:13px;font-family:var(--body-font);outline:none;appearance:none;cursor:pointer}

/* Banks page */
.banks-wrap{padding:80px 40px;max-width:700px;margin:0 auto}
.mode-toggle{display:flex;gap:0;margin:20px 0}
.mode-btn{padding:8px 18px;font-size:11px;font-weight:600;letter-spacing:0.04em;text-transform:uppercase;border:1px solid rgba(255,255,255,0.15);background:transparent;color:var(--text-secondary);cursor:pointer;font-family:var(--body-font);transition:all .2s}
.mode-btn:first-child{border-radius:var(--btn-radius) 0 0 var(--btn-radius)}
.mode-btn:last-child{border-radius:0 var(--btn-radius) var(--btn-radius) 0}
.mode-btn.active{background:rgba(255,255,255,0.1);color:var(--text-primary);border-color:rgba(255,255,255,0.25)}
.tier-tabs{display:flex;gap:0;margin:20px 0;background:rgba(255,255,255,0.04);border-radius:var(--border-radius);overflow:hidden}
.tier-tab{flex:1;padding:10px;font-size:11px;font-weight:500;text-align:center;border:none;background:transparent;color:var(--text-secondary);cursor:pointer;font-family:var(--body-font);transition:all .2s}
.tier-tab.active{background:rgba(255,255,255,0.08);color:var(--text-primary)}
.bank-pills{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}
.bank-pill{padding:8px 16px;border:1px solid rgba(255,255,255,0.15);border-radius:20px;font-size:12px;color:var(--text-secondary);cursor:pointer;transition:all .2s;font-family:var(--body-font)}
.bank-pill.selected{border-color:var(--accent-gold);color:var(--accent-gold);background:rgba(201,169,110,0.08)}
.bank-pill:hover{border-color:rgba(255,255,255,0.3)}
.search-bar{display:flex;gap:8px;margin:20px 0}
.search-bar input{flex:1;background:rgb(11,11,11);border:1px solid rgb(38,38,38);border-radius:var(--input-radius);padding:10px 16px;color:var(--text-primary);font-size:12px;font-family:var(--body-font)}
.search-bar button{padding:10px 20px;background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.15);border-radius:var(--btn-radius);color:var(--text-secondary);font-size:11px;font-weight:600;cursor:pointer;font-family:var(--body-font)}

/* Results page */
.results-wrap{display:grid;grid-template-columns:1fr 340px;gap:24px;padding:24px;max-width:1200px;margin:0 auto}
.results-main{display:flex;flex-direction:column;gap:24px}
.results-sidebar{display:flex;flex-direction:column;gap:16px}

/* Score card */
.score-card{background:var(--bg-card);border:1px solid rgba(255,255,255,0.08);border-radius:var(--border-radius);padding:24px;display:flex;gap:24px;align-items:center}
.score-circle{width:100px;height:100px;border-radius:50%;background:conic-gradient(var(--color-green) 0deg 342deg, rgba(46,204,113,0.15) 342deg);display:flex;flex-direction:column;align-items:center;justify-content:center;flex-shrink:0;position:relative}
.score-circle::after{content:'';position:absolute;inset:8px;border-radius:50%;background:var(--bg-card)}
.score-num{font-family:var(--heading-font);font-size:32px;font-weight:600;color:var(--color-green);position:relative;z-index:1}
.score-den{font-size:10px;color:var(--text-secondary);position:relative;z-index:1}
.score-info{flex:1}
.score-badge{display:inline-block;font-size:9px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;padding:4px 10px;border-radius:12px;background:rgba(46,204,113,0.12);color:var(--color-green);margin-bottom:8px}
.score-title{font-family:var(--heading-font);font-size:24px;font-weight:400;color:rgb(243,241,236);margin-bottom:6px;line-height:1.3}
.score-desc{font-size:13px;color:var(--text-secondary);line-height:1.5}

/* Category bars */
.cat-bars{display:flex;gap:12px;margin-top:16px;flex-wrap:wrap}
.cat-bar{flex:1;min-width:80px}
.cat-bar-label{font-size:9px;text-transform:uppercase;letter-spacing:0.08em;color:var(--text-secondary);font-weight:600;margin-bottom:4px}
.cat-bar-track{height:6px;background:rgba(255,255,255,0.06);border-radius:3px;overflow:hidden}
.cat-bar-fill{height:100%;background:var(--color-green);border-radius:3px;transition:width .5s}
.cat-bar-score{font-size:10px;color:var(--text-secondary);margin-top:3px}

/* Section headers */
.sec-header{font-size:12px;font-weight:600;letter-spacing:0.08em;text-transform:uppercase;color:var(--text-secondary);font-family:'Inter',sans-serif;display:flex;align-items:center;gap:10px}
.sec-badge{font-size:9px;font-weight:700;padding:3px 8px;border-radius:10px}
.sec-badge-red{background:rgba(231,76,60,0.12);color:var(--color-red)}
.sec-badge-green{background:rgba(46,204,113,0.12);color:var(--color-green)}

/* Issue cards */
.issue-card{background:var(--bg-card);border-radius:var(--border-radius);padding:20px;border-left:4px solid var(--color-orange)}
.issue-severity{font-size:9px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;margin-bottom:6px}
.issue-severity.warning{color:var(--color-orange)}
.issue-severity.critical{color:var(--color-red)}
.issue-title{font-size:16px;font-weight:600;color:var(--text-primary);margin-bottom:8px}
.issue-desc{font-size:13px;color:var(--text-secondary);line-height:1.6;margin-bottom:16px}
.issue-quote{background:rgba(255,255,255,0.04);border-radius:6px;padding:12px;margin-bottom:12px}
.issue-quote-label{font-size:8px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-secondary);font-weight:600;margin-bottom:6px}
.issue-quote-text{font-size:13px;font-style:italic;color:var(--accent-gold);line-height:1.5}
.issue-diff{background:rgba(255,255,255,0.03);border-radius:6px;padding:12px}
.issue-diff-label{font-size:8px;letter-spacing:0.12em;text-transform:uppercase;color:var(--text-secondary);font-weight:600;margin-bottom:8px}
.diff-old{text-decoration:line-through;color:var(--color-red);opacity:0.7;font-size:13px;margin-bottom:6px;line-height:1.5}
.diff-new{color:var(--color-green);font-size:13px;line-height:1.5}

/* Checklist */
.checklist{display:flex;flex-direction:column;gap:0}
.check-item{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid rgba(255,255,255,0.04)}
.check-icon{width:22px;height:22px;border-radius:50%;background:rgba(46,204,113,0.12);display:flex;align-items:center;justify-content:center;font-size:11px;color:var(--color-green);flex-shrink:0}
.check-info{flex:1}
.check-name{font-size:13px;font-weight:600;color:var(--text-primary)}
.check-desc{font-size:11px;color:var(--text-secondary);font-style:italic}
.pass-badge{font-size:9px;font-weight:700;padding:3px 10px;border-radius:10px;background:rgba(46,204,113,0.12);color:var(--color-green);text-transform:uppercase;letter-spacing:0.06em}

/* Sidebar cards */
.side-card{background:var(--bg-card);border:1px solid rgba(255,255,255,0.06);border-radius:var(--border-radius);padding:16px}
.side-card-title{font-size:12px;font-weight:600;letter-spacing:0.08em;text-transform:uppercase;color:var(--text-secondary);margin-bottom:12px;font-family:'Inter',sans-serif}
.bank-fit-row{display:flex;align-items:center;gap:10px;margin-bottom:8px}
.bank-fit-dot{width:8px;height:8px;border-radius:50%}
.bank-fit-name{font-size:13px;font-weight:600;color:var(--text-primary);flex:1}
.bank-fit-badge{font-size:9px;font-weight:700;padding:3px 8px;border-radius:10px}
.side-body{font-size:13px;color:var(--text-secondary);line-height:1.6}
.side-body strong{color:var(--accent-gold);font-weight:600;display:block;margin-bottom:4px}
.side-list{font-size:12px;color:var(--text-secondary);line-height:1.8;padding-left:16px}
.timeline-item{margin-bottom:12px}
.timeline-date{font-size:12px;font-weight:700;color:var(--accent-gold)}
.timeline-text{font-size:12px;color:var(--text-secondary);line-height:1.5}

/* Bullet rewriter */
.rewrite-card{background:var(--bg-card);border:1px solid rgba(255,255,255,0.06);border-radius:var(--border-radius);padding:20px;margin-bottom:16px}
.rewrite-label{font-size:8px;letter-spacing:0.12em;text-transform:uppercase;font-weight:700;margin-bottom:8px}
.rewrite-label.original{color:var(--text-secondary)}
.rewrite-label.optimized{color:var(--color-green)}
.rewrite-text{font-size:14px;color:var(--text-primary);line-height:1.6}
