def generate_card(card_data, section_id, first=False):
    tag_class = "dc-tag-cur" if first else "dc-tag-alt"
    tag_text = "Current" if first else "Alt"
    selected = 'selected' if first else ''
    var = card_data.get('var', '')
    val = card_data.get('val', '')

    return f'''<div class="dc-card {selected}" data-var="{var}" data-val="{val}" data-section="{section_id}" onclick="selectCard(this)">
<div class="dc-label"><span>{card_data["name"]}</span><span class="dc-tag {tag_class}">{tag_text}</span></div>
<div class="dc-preview">{card_data["html"]}</div>
<div class="dc-meta"><code>{card_data["code"]}</code></div>
</div>'''

def generate_section(section_num, title, note, cards):
    section_id = f"s{section_num}"
    cards_html = ''.join([generate_card(card, section_id, i==0) for i, card in enumerate(cards)])
    return f'''<div class="dc-section" id="{section_id}">
<div class="dc-section-title">{section_num} — {title}</div>
<div class="dc-note">{note}</div>
<div class="dc-grid">
{cards_html}
</div>
</div>
'''

